<script setup>
import { computed, onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import { Building2, Check, CheckCircle2, LoaderCircle, ShieldCheck } from 'lucide-vue-next'
import { getPublicForm, submitPublicForm } from '@/api/public-forms'
import { getPublicReferral, submitPublicReferral } from '@/api/referrals'
import PublicFormRenderer from '@/components/public-forms/PublicFormRenderer.vue'

const props = defineProps({ previewConfig: { type: Object, default: null } })
const route = useRoute(); const state = ref('loading'); const config = ref(null); const values = ref({}); const consents = ref({}); const errors = ref({}); const submitting = ref(false); const startedAt = ref(Date.now()); const honeypot = ref('')
const primary = computed(() => config.value?.form?.branding?.primaryColor || '#2563eb'); const form = computed(() => config.value?.form); const isReferral = computed(() => route.name === 'public-referral' || Boolean(props.previewConfig))
onMounted(async () => { if (props.previewConfig) { config.value = props.previewConfig; state.value = 'ready'; return } try { const { data } = await (isReferral.value ? getPublicReferral(route.params.token) : getPublicForm(route.params.token)); config.value = data; state.value = 'ready'; startedAt.value = Date.now() } catch { state.value = 'unavailable' } })
function validate() { const next = {}; for (const field of form.value.fields || []) { const value = values.value[field.key]; if (field.required && (value === undefined || value === null || value === '')) next[field.key] = 'Este campo é obrigatório.' } for (const [key, consent] of Object.entries(form.value.consent || {})) if (consent.enabled && consent.required && !consents.value[key]) next[`consent-${key}`] = 'Este consentimento é obrigatório.'; errors.value = next; return !Object.keys(next).length }
function requestKey() { return globalThis.crypto?.randomUUID?.() || `${Date.now()}-${Math.random().toString(36).slice(2)}` }
async function submit() { if (!validate() || props.previewConfig) return; submitting.value = true; try { const payload = { data: values.value, consents: consents.value, startedAt: startedAt.value, website: honeypot.value }; await (isReferral.value ? submitPublicReferral(route.params.token, payload, requestKey()) : submitPublicForm(route.params.token, payload, requestKey())); state.value = 'success' } catch (error) { errors.value = { submit: error.response?.data?.error?.message || error.response?.data?.message || 'Não foi possível enviar agora. Tente novamente.' } } finally { submitting.value = false } }
</script>

<template>
  <main class="public-page" :style="{ '--form-primary': primary }">
    <section v-if="state === 'loading'" class="state-card"><LoaderCircle class="spin" :size="32" /><p>Carregando formulário...</p></section>
    <section v-else-if="state === 'unavailable'" class="state-card"><ShieldCheck :size="40" /><h1>Formulário indisponível</h1><p>Este link não está mais disponível.</p></section>
    <section v-else-if="state === 'success'" class="state-card success"><div class="success-icon"><CheckCircle2 :size="42" /></div><h1>{{ form.success?.title || 'Tudo certo!' }}</h1><p>{{ form.success?.message || 'Recebemos seus dados.' }}</p><small>Você já pode fechar esta página com segurança.</small></section>
    <template v-else>
      <header class="page-header"><div class="clinic-brand"><img v-if="form.branding.logo" :src="form.branding.logo" :alt="form.branding.clinicName" /><span v-else class="logo-placeholder"><Building2 :size="20" /></span><strong>{{ form.branding.clinicName }}</strong></div></header>
      <section class="form-card"><img v-if="form.branding.coverImage" :src="form.branding.coverImage" class="cover-image" alt="" /><header class="form-header"><p v-if="isReferral && form.referrerName" class="referral-note">Você recebeu uma indicação de {{ form.referrerName }}.</p><h1>{{ form.branding.title }}</h1><p v-if="form.branding.description">{{ form.branding.description }}</p></header>
        <form @submit.prevent="submit" novalidate><PublicFormRenderer v-model="values" :form="form" :errors="errors" /><input v-model="honeypot" class="honeypot" tabindex="-1" autocomplete="off" aria-hidden="true" name="website" />
          <fieldset v-if="Object.values(form.consent || {}).some((item) => item.enabled)" class="consents"><legend>Consentimentos</legend><label v-for="(consent, key) in form.consent" v-show="consent.enabled" :key="key" class="consent" :class="{ accepted: consents[key], error: errors[`consent-${key}`] }"><input v-model="consents[key]" type="checkbox" /><span class="custom-checkbox"><Check :size="14" /></span><span class="consent-text">{{ consent.text }} <b v-if="consent.required">*</b></span></label><p v-for="(_, key) in form.consent" :key="`error-${key}`" v-show="errors[`consent-${key}`]" class="field-error">{{ errors[`consent-${key}`] }}</p></fieldset>
          <p v-if="errors.submit" class="submit-error" role="alert">{{ errors.submit }}</p><button type="submit" class="submit" :disabled="submitting"><LoaderCircle v-if="submitting" class="spin" :size="18" />{{ submitting ? 'Enviando...' : form.branding.buttonText }}</button>
        </form><footer><ShieldCheck :size="14" /> Seus dados são enviados de forma segura.</footer>
      </section>
    </template>
  </main>
</template>

<style scoped>
.public-page{min-height:100vh;background:#f9fafb;color:#1f2937;font-family:Inter,system-ui,sans-serif}.page-header{box-sizing:border-box;width:100%;padding:16px 24px;background:#fff;border-bottom:1px solid #e5e7eb}.clinic-brand{display:flex;align-items:center;gap:12px;width:min(100%,800px);margin:auto;color:#374151;font-size:16px}.clinic-brand img,.logo-placeholder{display:grid;place-items:center;width:40px;height:40px;border-radius:8px;object-fit:contain;background:#eef2ff;color:var(--form-primary)}.form-card,.state-card{box-sizing:border-box;width:min(calc(100% - 32px),800px);margin:32px auto;background:#fff;border:1px solid #e5e7eb;border-radius:16px;box-shadow:0 4px 20px rgb(0 0 0 / 7%);padding:38px 46px}.cover-image{display:block;width:calc(100% + 92px);max-height:280px;object-fit:cover;margin:-38px -46px 30px;border-radius:16px 16px 0 0}.form-header{margin-bottom:28px;text-align:center}.form-header h1{margin:0;color:#1f2937;font-size:28px;line-height:1.2}.form-header p{margin:10px auto 0;max-width:600px;color:#6b7280;font-size:15px;line-height:1.55}.form-header .referral-note{margin-bottom:12px;color:var(--form-primary);font-size:13px;font-weight:700}.form-card form{display:grid;gap:24px}.consents{display:grid;gap:10px;margin:0;padding:0;border:0}.consents legend{padding:0 0 2px;color:#374151;font-size:14px;font-weight:700}.consent{display:flex;align-items:flex-start;gap:11px;padding:12px 13px;border:1px solid #e5e7eb;border-radius:9px;background:#fafafa;color:#4b5563;font-size:13px;line-height:1.5;cursor:pointer;transition:border-color .18s,background .18s}.consent:hover{border-color:var(--form-primary);background:#f8fbff}.consent input{position:absolute;opacity:0;pointer-events:none}.custom-checkbox{display:grid;place-items:center;flex:0 0 21px;width:21px;height:21px;box-sizing:border-box;margin-top:1px;border:2px solid #cbd5e1;border-radius:5px;color:transparent;background:#fff}.custom-checkbox svg{display:none}.consent.accepted{border-color:color-mix(in srgb,var(--form-primary) 48%,#fff);background:#f8fbff}.consent.accepted .custom-checkbox{border-color:var(--form-primary);background:var(--form-primary);color:#fff}.consent.accepted .custom-checkbox svg{display:block}.consent.error{border-color:#dc2626}.consent-text b{color:#dc2626}.consent:has(input:focus-visible){outline:3px solid color-mix(in srgb,var(--form-primary) 18%,transparent)}.field-error,.submit-error{margin:0;color:#b91c1c;font-size:12px}.submit-error{padding:11px 13px;border:1px solid #fecaca;border-radius:8px;background:#fef2f2}.submit{display:flex;align-items:center;justify-content:center;gap:8px;width:100%;min-height:52px;border:0;border-radius:10px;background:var(--form-primary);color:#fff;font:inherit;font-weight:700;cursor:pointer;transition:filter .18s}.submit:hover:not(:disabled){filter:brightness(.94)}.submit:disabled{opacity:.7;cursor:wait}.honeypot{position:absolute;left:-10000px}.form-card footer{display:flex;justify-content:center;align-items:center;gap:6px;margin-top:23px;color:#9ca3af;font-size:12px}.state-card{display:grid;justify-items:center;gap:11px;max-width:480px;margin-top:10vh;text-align:center;color:#64748b}.state-card h1{margin:0;color:#1f2937;font-size:24px}.state-card p{margin:0;line-height:1.5}.success-icon{display:grid;place-items:center;width:82px;height:82px;border-radius:50%;background:#dcfce7;color:#16a34a}.state-card>svg{color:#e89b19}.spin{animation:spin 1s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}@media(max-width:600px){.page-header{padding:13px 16px}.form-card,.state-card{width:calc(100% - 24px);margin:12px auto;padding:26px 20px;border-radius:12px}.cover-image{width:calc(100% + 40px);margin:-26px -20px 24px;border-radius:12px 12px 0 0}.form-header h1{font-size:23px}.clinic-brand{font-size:14px}}
.public-page{padding-bottom:48px}.form-card{overflow:hidden;padding:0 0 38px;margin-bottom:48px}.cover-image{display:block;width:calc(100% - 92px);height:260px;max-height:none;margin:28px 46px 30px;border-radius:12px;object-fit:cover}.form-card>.form-header{margin:0 46px 28px}.form-card>form,.form-card>footer{margin-right:46px;margin-left:46px}@media(max-width:600px){.public-page{padding-bottom:24px}.form-card{padding:0 0 26px;margin-bottom:24px}.cover-image{width:calc(100% - 40px);height:190px;margin:20px 20px 24px;border-radius:10px}.form-card>.form-header{margin:0 20px 24px}.form-card>form,.form-card>footer{margin-right:20px;margin-left:20px}}
</style>
